def solve_equation():
    solutions = []
    limit = 5
    for x in range(1, limit + 1):
        for y in range(x, limit + 1):
            for z in range(y, limit + 1):
                lhs = x**3 + y**3 + z**3
                rhs = x**2 * y**2 * z**2
                if lhs == rhs:
                    solutions.append((x, y, z))
    return solutions

solutions = solve_equation()
print(solutions)

def check_equation(x, y, z):
    """Checks if x^3 + y^3 + z^3 = x^2*y^2*z^2"""
    lhs = x**3 + y**3 + z**3
    rhs = x**2 * y**2 * z**2
    return lhs == rhs

solutions = []
max_z = 10

# Iterate through z up to 10
for z in range(1, max_z + 1):
    # Iterate through y such that 1 <= y <= z
    for y in range(1, z + 1):
        # Iterate through x such that 1 <= x <= y
        for x in range(1, y + 1):
            if check_equation(x, y, z):
                solutions.append((x, y, z))

print(f"Found solutions up to z={max_z}: {solutions}")
